package com.cashflow.app.engine

import java.time.DayOfWeek
import java.time.LocalDate
import java.time.YearMonth

/** One stored row of a day as the day sheet lists it. */
data class DayItem(
    val tx: Transaction,
    /** Generated from a repeating payment / income source (it has a rule). */
    val fromSeries: Boolean,
    /** The final occurrence of a series that has an end date. */
    val last: Boolean = false,
    /** Generated by a DAILY income source (kept for the day sheet; every series income is left out of the month cells). */
    val dailyIncome: Boolean,
)

/**
 * Everything the calendar cell and the day sheet need for one date. All amounts are taken from the
 * engine's forecast, never recomputed: [expenses] and [closing] are the forecast's own numbers.
 */
data class DaySummary(
    val date: LocalDate,
    /** false for the leading/trailing days of the neighbouring months shown in the grid. */
    val inMonth: Boolean,
    val isToday: Boolean,
    val isPast: Boolean,
    /** false before the balance's start date: there is no forecast, so no closing balance. */
    val hasForecast: Boolean,
    /** Non-skipped expenses of the day (forecast.expenses). */
    val expenses: Long,
    /**
     * Non-skipped ONE-TIME income of the day. Income that comes from a repeating series (daily, weekly, monthly, ...)
     * is not shown on the calendar; it still counts in [closing].
     */
    val shownIncome: Long,
    /** The forecast's closing balance of the day. */
    val closing: Long,
    val negative: Boolean,
    /** PENDING items dated today or earlier: they are waiting for an answer. */
    val waiting: Int,
    /** Every stored row of the day, SKIPPED ones included. */
    val items: List<DayItem>,
) {
    val hasExpenses get() = expenses > 0
    val hasIncome get() = shownIncome > 0
}

data class MonthSummary(val month: YearMonth, val weeks: List<List<DaySummary>>) {
    fun day(date: LocalDate): DaySummary? = weeks.firstNotNullOfOrNull { week -> week.firstOrNull { it.date == date } }
}

object CalendarSummaries {
    /** Summaries of the whole grid of [month] (5 or 6 rows), built from the engine's forecast. */
    fun month(
        engine: BalanceEngine,
        rules: List<RecurringRule>,
        month: YearMonth,
        firstDayOfWeek: DayOfWeek,
        minRows: Int = CalendarGrid.MIN_ROWS,
    ): MonthSummary {
        val grid = CalendarGrid.weeks(month, firstDayOfWeek, minRows)
        val from = grid.first().first()
        val to = grid.last().last()
        val forecast = engine.forecast(from, to).associateBy { it.date }
        val dailyRuleIds = rules.filter { it.pattern == RecurrencePattern.Daily && it.kind == TxKind.INCOME }.map { it.id }.toSet()
        val lastDates = SeriesLast.lastDates(rules, engine.transactions)
        val today = engine.today
        val weeks = grid.map { week ->
            week.map { date -> summarize(forecast[date], date, month, today, dailyRuleIds, lastDates) }
        }
        return MonthSummary(month, weeks)
    }

    private fun summarize(f: DayForecast?, date: LocalDate, month: YearMonth, today: LocalDate, dailyRuleIds: Set<Long>, lastDates: Map<Long, LocalDate> = emptyMap()): DaySummary {
        val items = f?.items.orEmpty().map {
            DayItem(
                tx = it,
                fromSeries = it.recurringRuleId != null,
                last = it.recurringRuleId?.let { id -> lastDates[id] } == it.date && it.status != TxStatus.SKIPPED,
                dailyIncome = it.source == TxSource.RECURRING && it.kind == TxKind.INCOME && it.recurringRuleId in dailyRuleIds,
            )
        }
        val live = items.filter { it.tx.status != TxStatus.SKIPPED }
        val shownIncome = live.filter { it.tx.kind == TxKind.INCOME && !it.fromSeries }.sumOf { it.tx.amount }
        val waiting = live.count { it.tx.status == TxStatus.PENDING && !it.tx.date.isAfter(today) }
        return DaySummary(
            date = date,
            inMonth = YearMonth.from(date) == month,
            isToday = date == today,
            isPast = date.isBefore(today),
            hasForecast = f != null,
            expenses = f?.expenses ?: 0,
            shownIncome = shownIncome,
            closing = f?.closing ?: 0,
            negative = f != null && f.closing < 0,
            waiting = waiting,
            items = items,
        )
    }

    /** The first day (today or later) whose closing balance is negative; null when there is none. */
    fun firstShortDay(engine: BalanceEngine): LocalDate? = engine.negativeDays().firstOrNull()
}

/** Short amount text for a calendar cell: exact below 1000 TND, "1.3k" style above. No sign, no currency. */
object CompactAmount {
    fun format(millimes: Long): String {
        val abs = if (millimes < 0) -millimes else millimes
        if (abs < 1_000_000) return Money.format(Money.roundToCents(abs), withCurrency = false)
        if (abs < 1_000_000_000) return scaled(abs, 100_000L, 10_000_000L, 1_000_000L, "k")
        return scaled(abs, 100_000_000L, 10_000_000_000L, 1_000_000_000L, "M")
    }

    /** Units of 100 TND (or 100k) with one decimal below 10 units, whole units above. */
    private fun scaled(abs: Long, tenth: Long, tenUnits: Long, unit: Long, suffix: String): String {
        if (abs < tenUnits) {
            val tenths = (abs + tenth / 2) / tenth
            val text = if (tenths % 10 == 0L) "${tenths / 10}" else "${tenths / 10}.${tenths % 10}"
            return text + suffix
        }
        return "${(abs + unit / 2) / unit}$suffix"
    }

    /** A balance: "135", "1.2k", and "-10" when negative (red in the cell). */
    fun balance(millimes: Long): String = (if (millimes < 0) "-" else "") + format(millimes)

    /** "-75" / "+30". */
    fun signed(kind: TxKind, millimes: Long): String = (if (kind == TxKind.INCOME) "+" else "-") + format(millimes)
}

/** One line of a calendar cell: its text and its kind (so the screen can colour it). */
data class CellLine(val text: String, val kind: CellLineKind)

enum class CellLineKind { EXPENSE, INCOME, BALANCE }

/**
 * What a calendar cell shows, as a pure function of the day: the day number, then ALWAYS exactly three line slots:
 * (0) the day's expenses as a negative number, (1) one-time income, (2) the closing balance. A slot with nothing
 * to say is null but keeps its space, so the balances line up across cells. Nothing is ever left out for lack of room.
 */
data class CalendarCellContent(val dayNumber: Int, val lines: List<CellLine?>) {
    val expense get() = lines[EXPENSE_SLOT]
    val income get() = lines[INCOME_SLOT]
    val balance get() = lines[BALANCE_SLOT]

    companion object {
        const val SLOTS = 3
        const val EXPENSE_SLOT = 0
        const val INCOME_SLOT = 1
        const val BALANCE_SLOT = 2

        fun of(day: DaySummary): CalendarCellContent = CalendarCellContent(
            dayNumber = day.date.dayOfMonth,
            lines = listOf(
                if (day.hasExpenses) CellLine(CompactAmount.signed(TxKind.EXPENSE, day.expenses), CellLineKind.EXPENSE) else null,
                if (day.hasIncome) CellLine(CompactAmount.signed(TxKind.INCOME, day.shownIncome), CellLineKind.INCOME) else null,
                if (day.hasForecast) CellLine(CompactAmount.balance(day.closing), CellLineKind.BALANCE) else null,
            ),
        )
    }
}

/**
 * Sizes of a calendar cell, decided from the height of its row and the text scale. A cell is a day-number row at the
 * top plus three EQUAL slots (expenses, one-time income, balance) that fill the rest of the height; each text sits
 * in the middle of its slot, so the cell is used from top to bottom.
 */
data class CellMetrics(
    /** Height of one week row (dp). */
    val rowHeightDp: Float,
    /** Height of the day-number row at the top (dp). */
    val dayRowDp: Float,
    /** Height of each of the three equal slots (dp). */
    val slotDp: Float,
    val daySp: Float,
    /** Size of the balance (the biggest line). */
    val balanceSp: Float,
    /** Size of the expense and income lines. */
    val moneySp: Float,
    /** The rows need more room than there is even at the smallest text size, so the grid area scrolls. */
    val scrolls: Boolean,
)

/**
 * One fixed cell layout at every font scale and row count. When room is short the TEXT gets smaller (down to
 * [MIN_SP]) instead of lines disappearing. A pure function of its inputs: nothing depends on a first measurement.
 */
object CalendarCellLayout {
    const val MIN_SP = 8f
    const val DAY_SP = 11f
    const val BALANCE_SP = 16f
    const val MONEY_SP = 12f

    /** Line height as a multiple of the text size. */
    const val LINE = 1.15f

    /** Space above, between and below the lines (dp). */
    const val PAD_DP = 4f

    /** Slots in a cell: expenses, one-time income, balance. */
    const val SLOTS = CalendarCellContent.SLOTS

    private fun scaleOf(fontScale: Float) = if (fontScale <= 0f) 1f else fontScale

    /** Height of the day-number row (dp) at text scale [fontScale]. */
    fun dayRowDp(fontScale: Float): Float = DAY_SP * LINE * scaleOf(fontScale)

    /** The height (dp) a cell needs when its three slots are as small as the smallest text allows. */
    fun neededHeightDp(fontScale: Float): Float = PAD_DP + dayRowDp(fontScale) + SLOTS * MIN_SP * LINE * scaleOf(fontScale)

    /** Metrics for [rows] rows sharing [availableHeightDp]. */
    fun metrics(availableHeightDp: Float, rows: Int, fontScale: Float): CellMetrics =
        forRow(if (rows <= 0) 0f else availableHeightDp / rows, fontScale)

    /** Metrics for one row [rowHeightDp] tall. */
    fun forRow(rowHeightDp: Float, fontScale: Float): CellMetrics {
        val scale = scaleOf(fontScale)
        val dayRow = dayRowDp(scale)
        val slot = (rowHeightDp - PAD_DP - dayRow) / SLOTS
        // The biggest text size at which one line fits its slot.
        val fits = slot / (LINE * scale)
        if (fits < MIN_SP) {
            // Not even the smallest size fits: keep it readable and let the grid area scroll.
            val minSlot = MIN_SP * LINE * scale
            return CellMetrics(neededHeightDp(scale), dayRow, minSlot, DAY_SP, MIN_SP, MIN_SP, scrolls = true)
        }
        return CellMetrics(rowHeightDp, dayRow, slot, DAY_SP, minOf(BALANCE_SP, fits), minOf(MONEY_SP, fits), scrolls = false)
    }

    /**
     * The text size (sp) at which [text] fits [widthDp] on one line, at most [maxSp] and at least [MIN_SP]. Digits and
     * signs are about 0.6 em wide; the text never wraps, never gets an ellipsis and is never dropped.
     */
    fun fitSp(text: String, widthDp: Float, maxSp: Float, fontScale: Float): Float {
        if (text.isEmpty() || widthDp <= 0f) return maxSp
        val scale = if (fontScale <= 0f) 1f else fontScale
        val fits = widthDp / (text.length * CHAR_EM * scale)
        return fits.coerceIn(MIN_SP, maxSp)
    }

    private const val CHAR_EM = 0.6f
}
